const lat1 = 37.7749, lon1 = -122.4194; // San Francisco, CA
const lat2 = 42.3396, lon2 = -71.0640;  // Boston, MA 02118

const R = 6371; // Earth's radius in km
const dLat = (lat2 - lat1) * Math.PI / 180;
const dLon = (lon2 - lon1) * Math.PI / 180;
const a = Math.sin(dLat/2)**2 +
          Math.cos(lat1 * Math.PI/180) * Math.cos(lat2 * Math.PI/180) *
          Math.sin(dLon/2)**2;
const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
const distKm = R * c;
const distMi = distKm * 0.621371;

console.log('=== Distance Estimate ===');
console.log('From: San Francisco, CA (37.7749°N, 122.4194°W)');
console.log('To:   4829 Elm Ridge Way, Suite 7, Boston, MA 02118');
console.log('      (approx. 42.3396°N, 71.0640°W)');
console.log('');
console.log('Straight-line (great-circle) distance:');
console.log('  ' + distKm.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' km');
console.log('  ' + distMi.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' miles');
console.log('');
console.log('Note: Actual driving distance is typically 15–30% longer.');
console.log('Estimated driving distance: ~' + Math.round(distMi*1.2).toLocaleString() + '–' + Math.round(distMi*1.3).toLocaleString() + ' miles');
"
